changeSet.sql:
CREATE OR ALTER TRIGGER [dbo].[Field_AfterUpsert] ON [dbo].[Field] FOR INSERT, UPDATE AS SET NOCOUNT ON;
-- formatted value logic only needs to run in cases where value is not null if exists( select 1 from inserted where [value] is not null) begin
UPDATE T SET T.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.ObjectType = T.ObjectType and F.ObjectID = T.ObjectID and F.ObjectType <> 'FusionAttribute' and F.ObjectType <> 'FusionQueryAttribute' and F.[Value] is not null INNER JOIN FieldType FT ON FT.ID = T.FieldTypeID;
drop table if exists #insertedFields; create table #insertedFields (ObjectType varchar(250), ObjectID int); create clustered index IX_TempInsertedFields ON #insertedFields (ObjectType, ObjectID);
insert into #insertedFields select distinct replace(FT.[Object],'Type',''), FT.ObjectID from inserted i inner join FieldType FT on FT.ID = i.FieldTypeID where exists (select 1 from deleted d where d.id = i.id);
if exists( select 1 from Field TF inner join FieldType FT on FT.ID = TF.FieldTypeID inner join #insertedFields SF on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID where SF.ObjectType <> 'FusionAttribute' and SF.ObjectType <> 'FusionQueryAttribute' and TF.[Value] is not null) begin
UPDATE TF SET TF.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, TF.Value, FT.AllowMultipleValues) from Field TF inner join FieldType FT on FT.ID = TF.FieldTypeID inner join #insertedFields SF on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID where SF.ObjectType <> 'FusionAttribute' and SF.ObjectType <> 'FusionQueryAttribute' and TF.[Value] is not null; end end
-- only update the assetid field if one was not already provided if exists( select 1 from inserted where AssetID is null ) begin UPDATE T SET T.AssetID = A.ID FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.ObjectType = T.ObjectType and F.ObjectID = T.ObjectID and T.AssetID is null inner join Asset A on A.Object = F.ObjectType and A.ObjectID = F.ObjectID; end

changeSet.rollback:
CREATE OR ALTER TRIGGER [dbo].[Field_AfterUpsert] ON [dbo].[Field] FOR INSERT, UPDATE AS SET NOCOUNT ON;
UPDATE T SET T.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.ObjectType = T.ObjectType and F.ObjectID = T.ObjectID and F.ObjectType <> 'FusionAttribute' and F.ObjectType <> 'FusionQueryAttribute' INNER JOIN FieldType FT ON FT.ID = T.FieldTypeID;
drop table if exists #insertedFields; create table #insertedFields (ObjectType varchar(250), ObjectID int); create clustered index IX_TempInsertedFields ON #insertedFields (ObjectType, ObjectID);
insert into #insertedFields select distinct replace(FT.[Object],'Type',''), FT.ObjectID from inserted i inner join FieldType FT on FT.ID = i.FieldTypeID where exists (select 1 from deleted d where d.id = i.id);
if exists( select 1 from Field TF inner join FieldType FT on FT.ID = TF.FieldTypeID inner join #insertedFields SF on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID where SF.ObjectType <> 'FusionAttribute' and SF.ObjectType <> 'FusionQueryAttribute') begin
UPDATE TF SET TF.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, TF.Value, FT.AllowMultipleValues) from Field TF inner join FieldType FT on FT.ID = TF.FieldTypeID inner join #insertedFields SF on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID where SF.ObjectType <> 'FusionAttribute' and SF.ObjectType <> 'FusionQueryAttribute'; end
-- only update the assetid field if one was not already provided if exists( select 1 from inserted where AssetID is null ) begin UPDATE T SET T.AssetID = A.ID FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.ObjectType = T.ObjectType and F.ObjectID = T.ObjectID and T.AssetID is null inner join Asset A on A.Object = F.ObjectType and A.ObjectID = F.ObjectID; end
